-- ASSUMPTION: leads.ad_id, leads.qualified (bool), leads.created_at, leads.brand_id exist per build/crm-gap.md. booked / attended / cost_per_attended are joined from bookings + outcomes by W29 once those tables exist.
UPDATE ad_metrics m SET qualified = s.q, cost_per_qualified = CASE WHEN s.q > 0 THEN round(m.spend_zar / s.q, 2) END
FROM (SELECT ad_id, (created_at AT TIME ZONE 'Africa/Johannesburg')::date AS d, count(*) FILTER (WHERE qualified) AS q FROM leads WHERE brand_id = $1::uuid AND ad_id IS NOT NULL AND created_at > now() - interval '5 days' GROUP BY 1, 2) s
WHERE m.ad_id = s.ad_id AND m.date = s.d AND m.brand_id = $1::uuid;
UPDATE brands SET insights_last_fetched_at = $2::timestamptz WHERE brand_id = $1::uuid;
